static int device_show ( struct seq_file * s , void * v ) { struct nitrox_device * ndev = s -> private ; seq_printf ( s , "NITROX [%d]\n" , ndev -> idx ) ; seq_printf ( s , "  Part Name: %s\n" , ndev -> hw . partname ) ; seq_printf ( s , "  Frequency: %d MHz\n" , ndev -> hw . freq ) ; seq_printf ( s , "  Device ID: 0x%0x\n" , ndev -> hw . device_id ) ; seq_printf ( s , "  Revision ID: 0x%0x\n" , ndev -> hw . revision_id ) ; return 0 ; } 